pirate_dreadnought_flagship.source:
export const envelope = [25, 30, 50];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 12; // Center X axis of the warship

  function clean(str) {
    return str ? str.replace(/\[.*\]/, "") : "";
  }

  const woodPlanks = api.theme.wood.planks;
  const woodLog = clean(api.theme.wood.log);
  const woodStripped = clean(api.theme.wood.stripped);
  const woodStairs = clean(api.theme.wood.stairs);
  const woodFence = clean(api.theme.wood.fence);
  const woodTrapdoor = clean(api.theme.wood.trapdoor);

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Declared interior spaces for compiler fit-out (Rule 6 & Interiors rule)
  const interiors = [
    { min: [8, 5, 12], max: [16, 7, 33], kind: "hold" },
    { min: [8, 10, 36], max: [16, 12, 44], kind: "quarters" },
    { min: [9, 6, 7], max: [15, 8, 11], kind: "quarters" }
  ];

  function isInteriorAir(x, y, z) {
    for (const room of interiors) {
      if (x >= room.min[0] && x <= room.max[0] &&
          y >= room.min[1] && y <= room.max[1] &&
          z >= room.min[2] && z <= room.max[2]) {
        // Mast cores continue through interiors
        if (x === cx && (z === 23 || z === 11 || z === 35)) return false;
        return true;
      }
    }
    return false;
  }

  // Hull profile curves along longitudinal axis Z
  function getProfile(z) {
    if (z < 4 || z > 46) return null;
    let yBot, yDeck, halfW, yRail;

    if (z <= 8) {
      const t = (z - 4) / 4;
      yBot = 4 - t * 1;
      yDeck = 9;
      halfW = 1.2 + t * 2.3;
      yRail = 10 + Math.round(t);
    } else if (z <= 14) {
      const t = (z - 8) / 6;
      yBot = 3 - t * 1;
      yDeck = 9 - Math.round(t * 1);
      halfW = 3.5 + t * 2.0;
      yRail = 11 - Math.round(t * 1);
    } else if (z <= 32) {
      const t = (z - 14) / 18;
      yBot = 2;
      yDeck = 8;
      const mid = Math.sin(t * Math.PI);
      halfW = 5.5 + mid * 0.8;
      yRail = 10;
    } else if (z <= 38) {
      const t = (z - 32) / 6;
      yBot = 2 + t * 1;
      yDeck = 10;
      halfW = 5.5 - t * 0.4;
      yRail = 12;
    } else {
      const t = (z - 38) / 8;
      yBot = 3 + t * 1;
      yDeck = 13;
      halfW = 5.1 - t * 0.9;
      yRail = 15 + Math.round(t * 2);
    }

    return {
      yBot: Math.round(yBot),
      yDeck: Math.round(yDeck),
      halfW,
      yRail: Math.round(yRail)
    };
  }

  // 1. Build Hull, Foundations, Keel & Decks
  for (let z = 4; z <= 46; z++) {
    const prof = getProfile(z);
    if (!prof) continue;

    const { yBot, yDeck, halfW, yRail } = prof;

    for (let x = Math.floor(cx - halfW - 1); x <= Math.ceil(cx + halfW + 1); x++) {
      const dx = Math.abs(x - cx);

      // Terrain conformance: extend downwards to terrain heightAt (Rule 6)
      if (dx <= halfW) {
        const groundY = Math.floor(api.heightAt(x, z));
        const minY = Math.max(0, Math.min(yBot, groundY));
        for (let y = minY; y < yBot; y++) {
          if (dx === 0) {
            set(x, y, z, `${woodLog}[axis=y]`);
          } else if (dx <= 2) {
            set(x, y, z, woodPlanks);
          } else {
            set(x, y, z, `${woodLog}[axis=y]`);
          }
        }
      }

      // Hull framing from yBot up to yRail
      for (let y = yBot; y <= yRail; y++) {
        let wAtY;
        if (y <= yDeck) {
          const yRel = Math.max(0.1, (y - yBot) / Math.max(1, yDeck - yBot));
          wAtY = halfW * Math.pow(yRel, 0.55);
        } else {
          wAtY = halfW - (y - yDeck) * 0.15;
        }

        if (dx <= wAtY) {
          const isOuterWall = (dx >= wAtY - 1.15) || (z === 46 && dx <= wAtY) || (z === 4);
          const isKeel = (dx === 0 && y === yBot);
          const isDeckLevel = (y === 4 && z >= 10 && z <= 34) || (y === yDeck && y <= 13);

          if (isKeel) {
            set(x, y, z, `${woodLog}[axis=z]`);
          } else if (isOuterWall) {
            const isGunportZ = (z === 15 || z === 19 || z === 23 || z === 27 || z === 31);
            if (y === 6 && isGunportZ && (dx >= wAtY - 1.0)) {
              // Open gunport - handled by cannon placement pass
              continue;
            }
            if (y === yDeck || y === yBot + 1 || y === yRail) {
              set(x, y, z, `${woodStripped}[axis=z]`);
            } else {
              set(x, y, z, woodPlanks);
            }
          } else if (isDeckLevel) {
            const isHatch = (y === 8 && dx <= 1 && ((z >= 17 && z <= 19) || (z >= 27 && z <= 29)));
            if (isHatch) {
              set(x, y, z, `${woodTrapdoor}[facing=north,half=bottom,open=false]`);
            } else {
              set(x, y, z, woodPlanks);
            }
          } else {
            // Keep interior air empty for compiler fitout
            if (!isInteriorAir(x, y, z)) {
              if (z === 13 && y <= 9) {
                if (dx !== 0 || y > 7) {
                  set(x, y, z, woodPlanks);
                } else {
                  set(x, y, z, "minecraft:air");
                }
              } else if (z === 34 && y <= 13) {
                if (dx !== 0 || (y !== 10 && y !== 11)) {
                  set(x, y, z, woodPlanks);
                } else {
                  set(x, y, z, "minecraft:air");
                }
              }
            }
          }
        }
      }
    }
  }

  // 2. Broadside Heavy Cannons (Lower Tier Y = 6)
  const cannonZs = [15, 19, 23, 27, 31];
  for (const cz of cannonZs) {
    const prof = getProfile(cz);
    if (!prof) continue;
    const w6 = prof.halfW * Math.pow((6 - prof.yBot) / Math.max(1, prof.yDeck - prof.yBot), 0.55);
    const leftX = Math.round(cx - w6);
    const rightX = Math.round(cx + w6);

    // Port Gun
    set(leftX + 1, 5, cz, woodPlanks);
    set(leftX + 1, 6, cz, "minecraft:dispenser[facing=west]");
    set(leftX, 6, cz, "minecraft:polished_blackstone_wall");
    set(leftX + 1, 7, cz, `${woodTrapdoor}[facing=west,half=bottom,open=false]`);

    // Starboard Gun
    set(rightX - 1, 5, cz, woodPlanks);
    set(rightX - 1, 6, cz, "minecraft:dispenser[facing=east]");
    set(rightX, 6, cz, "minecraft:polished_blackstone_wall");
    set(rightX - 1, 7, cz, `${woodTrapdoor}[facing=east,half=bottom,open=false]`);
  }

  // Upper Deck Swivel Cannons (Y = 9)
  const upperCannonZs = [17, 21, 25, 29];
  for (const cz of upperCannonZs) {
    const prof = getProfile(cz);
    if (!prof) continue;
    const leftX = Math.round(cx - prof.halfW);
    const rightX = Math.round(cx + prof.halfW);

    set(leftX, 9, cz, "minecraft:dispenser[facing=west]");
    set(leftX - 1, 9, cz, "minecraft:iron_bars");

    set(rightX, 9, cz, "minecraft:dispenser[facing=east]");
    set(rightX + 1, 9, cz, "minecraft:iron_bars");
  }

  // 3. Menacing Iron Ram & Beast Skull Figurehead (Pointing North / -Z)
  // Sharp nose at Z = 0
  set(cx, 6, 0, "minecraft:iron_block");
  set(cx, 5, 0, "minecraft:iron_block");

  // Ram spike at Z = 1
  set(cx, 5, 1, "minecraft:iron_block");
  set(cx, 6, 1, "minecraft:iron_block");
  set(cx, 7, 1, "minecraft:iron_block");
  set(cx - 1, 6, 1, "minecraft:iron_bars");
  set(cx + 1, 6, 1, "minecraft:iron_bars");

  // Heavy ram body at Z = 2
  for (let y = 5; y <= 7; y++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      set(x, y, 2, "minecraft:iron_block");
    }
  }
  set(cx - 2, 6, 2, "minecraft:iron_bars");
  set(cx + 2, 6, 2, "minecraft:iron_bars");

  // Ram base at Z = 3
  for (let y = 5; y <= 7; y++) {
    for (let x = cx - 2; x <= cx + 2; x++) {
      set(x, y, 3, "minecraft:iron_block");
    }
  }

  // Foundation under the ram
  for (let z = 0; z <= 3; z++) {
    const groundY = Math.floor(api.heightAt(cx, z));
    for (let y = Math.max(0, groundY); y < 5; y++) {
      set(cx, y, z, "minecraft:iron_block");
    }
  }

  // Beast Figurehead / Skull above Ram (Z = 2..5, Y = 8..12)
  set(cx, 8, 3, "minecraft:bone_block");
  set(cx, 9, 3, "minecraft:bone_block");
  set(cx, 10, 3, "minecraft:bone_block");
  set(cx, 9, 2, "minecraft:bone_block");
  set(cx, 10, 2, "minecraft:bone_block");
  set(cx - 1, 9, 2, "minecraft:polished_blackstone");
  set(cx + 1, 9, 2, "minecraft:polished_blackstone");
  set(cx - 1, 10, 3, "minecraft:bone_block");
  set(cx + 1, 10, 3, "minecraft:bone_block");
  set(cx - 1, 11, 4, "minecraft:bone_block");
  set(cx + 1, 11, 4, "minecraft:bone_block");
  set(cx - 2, 12, 5, "minecraft:bone_block");
  set(cx + 2, 12, 5, "minecraft:bone_block");
  set(cx, 8, 2, "minecraft:soul_lantern[hanging=false]");

  // Bowsprit spar angling forward over the ram
  const bowspritPoints = [
    [cx, 10, 7], [cx, 10, 6], [cx, 11, 5], [cx, 11, 4],
    [cx, 12, 3], [cx, 13, 2], [cx, 14, 1]
  ];
  for (const [bx, by, bz] of bowspritPoints) {
    set(bx, by, bz, `${woodLog}[axis=z]`);
  }
  set(cx, 14, 0, "minecraft:chain");
  set(cx, 13, 0, "minecraft:chain");
  set(cx, 12, 1, "minecraft:chain");
  set(cx, 11, 2, "minecraft:chain");
  set(cx, 10, 3, "minecraft:chain");

  // 4. Sterncastle, Stern Gallery & Skull Carvings (Z = 45..46)
  // Rudder at stern
  for (let y = 1; y <= 6; y++) {
    const groundY = Math.floor(api.heightAt(cx, 46));
    if (y >= Math.max(0, groundY)) {
      set(cx, y, 46, `${woodLog}[axis=y]`);
      set(cx, y, 47, `${woodTrapdoor}[facing=south,half=bottom,open=false]`);
    }
  }

  // Great Cabin Windows (Z = 45, Y = 10..12)
  for (let x = cx - 3; x <= cx + 3; x++) {
    for (let y = 10; y <= 12; y++) {
      if (x === cx || Math.abs(x - cx) === 2) {
        set(x, y, 45, `${woodLog}[axis=y]`);
      } else {
        set(x, y, 45, `${woodFence}`);
      }
    }
  }

  // Stern Balconies
  for (let x = cx - 3; x <= cx + 3; x++) {
    set(x, 9, 46, woodPlanks);
    set(x, 10, 46, `${woodFence}`);
  }
  set(cx - 3, 11, 46, "minecraft:soul_lantern[hanging=false]");
  set(cx + 3, 11, 46, "minecraft:soul_lantern[hanging=false]");

  for (let x = cx - 2; x <= cx + 2; x++) {
    set(x, 13, 46, woodPlanks);
    set(x, 14, 46, `${woodFence}`);
  }

  // SKULL & CROSSBONES carved across sterncastle transom
  // Center Skull
  set(cx - 1, 16, 45, "minecraft:bone_block");
  set(cx, 16, 45, "minecraft:bone_block");
  set(cx + 1, 16, 45, "minecraft:bone_block");
  set(cx, 15, 45, "minecraft:bone_block");
  set(cx - 1, 15, 45, "minecraft:polished_blackstone");
  set(cx + 1, 15, 45, "minecraft:polished_blackstone");
  set(cx - 1, 14, 45, "minecraft:bone_block");
  set(cx, 14, 45, "minecraft:bone_block");
  set(cx + 1, 14, 45, "minecraft:bone_block");

  // Crossed Bones
  set(cx - 2, 17, 45, "minecraft:bone_block");
  set(cx - 3, 18, 45, "minecraft:bone_block");
  set(cx + 2, 17, 45, "minecraft:bone_block");
  set(cx + 3, 18, 45, "minecraft:bone_block");
  set(cx - 2, 13, 45, "minecraft:bone_block");
  set(cx - 3, 12, 45, "minecraft:bone_block");
  set(cx + 2, 13, 45, "minecraft:bone_block");
  set(cx + 3, 12, 45, "minecraft:bone_block");

  // Stern Post Great Lantern
  set(cx, 18, 46, `${woodFence}`);
  set(cx, 19, 46, `${woodFence}`);
  set(cx, 20, 46, "minecraft:soul_lantern[hanging=false]");

  // Ship's Helm on Poop Deck
  set(cx, 14, 40, `${woodFence}`);
  set(cx, 15, 40, `${woodTrapdoor}[facing=south,half=bottom,open=false]`);
  set(cx - 1, 14, 40, `${woodStairs}[facing=east,half=bottom]`);
  set(cx + 1, 14, 40, `${woodStairs}[facing=west,half=bottom]`);

  // 5. Masts, Yards & Torn Black Sails
  function buildTornSail(mastX, mastZ, yardY, height, width) {
    const halfW = Math.floor(width / 2);
    for (let yOff = 0; yOff < height; yOff++) {
      const curY = yardY - yOff;
      const tY = yOff / height;
      const billowZ = Math.round(Math.sin(tY * Math.PI) * 1.5);
      const targetZ = mastZ - billowZ;
      const curHalfW = Math.max(1, Math.round(halfW * (1.0 - tY * 0.15)));

      for (let dx = -curHalfW; dx <= curHalfW; dx++) {
        const curX = mastX + dx;
        if (curX === mastX && targetZ === mastZ) continue;

        const isEdge = Math.abs(dx) >= curHalfW - 1;
        const isBottom = yOff >= height - 2;
        const tearHash = ((curX * 37) ^ (curY * 19) ^ (mastZ * 43)) & 0xFF;

        if (isBottom && (tearHash % 5 === 0)) continue;
        if (isEdge && (tearHash % 7 === 0)) continue;

        // Skull motif on main course sail
        if (mastZ === 23 && yardY === 15 && Math.abs(dx) <= 1 && curY >= 12 && curY <= 14) {
          if (curY === 13 && dx === 0) {
            set(curX, curY, targetZ, "minecraft:polished_blackstone");
          } else {
            set(curX, curY, targetZ, "minecraft:bone_block");
          }
        } else if (tearHash % 13 === 0) {
          set(curX, curY, targetZ, "minecraft:gray_wool");
        } else {
          set(curX, curY, targetZ, "minecraft:black_wool");
        }
      }
    }
  }

  // --- FOREMAST (Z = 11) ---
  for (let y = 8; y <= 27; y++) {
    set(cx, y, 11, `${woodLog}[axis=y]`);
  }
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      set(cx + dx, 20, 11 + dz, woodPlanks);
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        set(cx + dx, 21, 11 + dz, `${woodFence}`);
      }
    }
  }
  for (let x = cx - 5; x <= cx + 5; x++) {
    set(x, 15, 11, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 11, 15, 5, 11);

  for (let x = cx - 3; x <= cx + 3; x++) {
    set(x, 23, 11, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 11, 23, 4, 7);

  // --- MAINMAST (Z = 23) ---
  for (let y = 5; y <= 29; y++) {
    set(cx, y, 23, `${woodLog}[axis=y]`);
  }
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      set(cx + dx, 22, 23 + dz, woodPlanks);
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        set(cx + dx, 23, 23 + dz, `${woodFence}`);
      }
    }
  }
  for (let x = cx - 6; x <= cx + 6; x++) {
    set(x, 15, 23, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 23, 15, 6, 13);

  for (let x = cx - 4; x <= cx + 4; x++) {
    set(x, 22, 23, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 23, 22, 4, 9);

  for (let x = cx - 2; x <= cx + 2; x++) {
    set(x, 26, 23, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 23, 26, 3, 5);

  // Jolly Roger masthead pennant
  set(cx, 28, 23, `${woodFence}`);
  set(cx, 29, 23, `${woodFence}`);
  set(cx, 29, 22, "minecraft:black_wool");
  set(cx, 29, 21, "minecraft:black_wool");
  set(cx, 28, 22, "minecraft:black_wool");
  set(cx, 28, 21, "minecraft:bone_block");

  // --- MIZZENMAST (Z = 35) ---
  for (let y = 10; y <= 26; y++) {
    set(cx, y, 35, `${woodLog}[axis=y]`);
  }
  for (let x = cx - 4; x <= cx + 4; x++) {
    set(x, 18, 35, `${woodStripped}[axis=x]`);
  }
  buildTornSail(cx, 35, 18, 4, 9);

  // Mizzen spanker sail angled back over stern
  for (let dz = 1; dz <= 7; dz++) {
    const curZ = 35 + dz;
    const boomY = 13 + Math.round(dz * 0.3);
    const gaffY = 18 + Math.round(dz * 0.4);
    set(cx, boomY, curZ, `${woodFence}`);
    set(cx, gaffY, curZ, `${woodFence}`);
    for (let y = boomY + 1; y < gaffY; y++) {
      if ((dz + y) % 6 !== 0) {
        set(cx, y, curZ, "minecraft:black_wool");
      }
    }
  }

  // --- SHROUDS & STAYS ---
  const mastConfigs = [
    { z: 11, yTop: 20, yBot: 9, w: 4 },
    { z: 23, yTop: 22, yBot: 8, w: 6 },
    { z: 35, yTop: 18, yBot: 10, w: 5 }
  ];

  for (const m of mastConfigs) {
    for (let dz = -1; dz <= 1; dz++) {
      const rz = m.z + dz;
      const lx = cx - m.w;
      for (let y = m.yBot; y <= m.yTop; y++) {
        const t = (y - m.yBot) / (m.yTop - m.yBot);
        const curX = Math.round(lx + t * (cx - lx));
        set(curX, y, rz, `${woodFence}`);
      }
      const rx = cx + m.w;
      for (let y = m.yBot; y <= m.yTop; y++) {
        const t = (y - m.yBot) / (m.yTop - m.yBot);
        const curX = Math.round(rx - t * (rx - cx));
        set(curX, y, rz, `${woodFence}`);
      }
    }
  }

  // Forestays
  for (let z = 5; z <= 10; z++) {
    const t = (z - 5) / 5;
    const stayY = Math.round(11 + t * (20 - 11));
    set(cx, stayY, z, "minecraft:chain");
  }
  for (let z = 12; z <= 22; z++) {
    const t = (z - 12) / 10;
    const stayY = Math.round(17 + t * (22 - 17));
    set(cx, stayY, z, "minecraft:chain");
  }
  for (let z = 24; z <= 34; z++) {
    const t = (z - 24) / 10;
    const stayY = Math.round(20 - t * 4);
    set(cx, stayY, z, "minecraft:chain");
  }

  // 6. Bower Anchors on Bow Quarters
  set(cx - 3, 8, 7, "minecraft:chain");
  set(cx - 3, 7, 7, "minecraft:iron_block");
  set(cx - 3, 6, 7, "minecraft:iron_bars");
  set(cx - 3, 6, 6, "minecraft:iron_bars");
  set(cx - 3, 6, 8, "minecraft:iron_bars");

  set(cx + 3, 8, 7, "minecraft:chain");
  set(cx + 3, 7, 7, "minecraft:iron_block");
  set(cx + 3, 6, 7, "minecraft:iron_bars");
  set(cx + 3, 6, 6, "minecraft:iron_bars");
  set(cx + 3, 6, 8, "minecraft:iron_bars");

  // 7. Companionways, Ladders & Deck Stairs
  // Forecastle to Waist
  set(cx - 2, 8, 14, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 2, 8, 14, `${woodStairs}[facing=north,half=bottom]`);

  // Waist to Quarterdeck
  set(cx - 3, 8, 32, `${woodStairs}[facing=north,half=bottom]`);
  set(cx - 3, 9, 33, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 3, 8, 32, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 3, 9, 33, `${woodStairs}[facing=north,half=bottom]`);

  // Quarterdeck to Poop Deck
  set(cx - 3, 10, 37, `${woodStairs}[facing=north,half=bottom]`);
  set(cx - 3, 11, 37, `${woodStairs}[facing=north,half=bottom]`);
  set(cx - 3, 12, 38, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 3, 10, 37, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 3, 11, 37, `${woodStairs}[facing=north,half=bottom]`);
  set(cx + 3, 12, 38, `${woodStairs}[facing=north,half=bottom]`);

  // Access ladders to lower decks
  for (let y = 5; y <= 7; y++) {
    set(cx, y, 17, "minecraft:ladder[facing=south]");
  }
  for (let y = 6; y <= 8; y++) {
    set(cx, y, 12, "minecraft:ladder[facing=south]");
  }

  return {
    name: "pirate_dreadnought_flagship",
    seatY: 0,
    anchors: {
      front: [cx, 6, 0],
      ram: [cx, 6, 0],
      helm: [cx, 14, 40],
      deck: [cx, 8, 20]
    },
    interiors
  };
}

