export const envelope = [23, 42, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 8;

  // World Theme Palette Roles
  const stonePrimary = api.theme.stone?.primary || "minecraft:quartz_block";
  const stoneAccent = api.theme.stone?.accent || "minecraft:smooth_quartz";
  const stoneStairsRaw = api.theme.stone?.stairs || "minecraft:smooth_quartz_stairs";
  const stoneSlabRaw = api.theme.stone?.slab || "minecraft:smooth_quartz_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";
  const groundPlinth = api.theme.ground?.plinth || "minecraft:deepslate_bricks";
  const groundPave = api.theme.ground?.pavement || "minecraft:smooth_quartz";

  // Celestial Colossus & Amethyst Materials (Rule 7 exception for magical sculpture)
  const Q_BLOCK = "minecraft:quartz_block";
  const Q_SMOOTH = "minecraft:smooth_quartz";
  const Q_BRICKS = "minecraft:quartz_bricks";
  const Q_PILLAR = "minecraft:quartz_pillar[axis=y]";
  const Q_PILLAR_Z = "minecraft:quartz_pillar[axis=z]";
  const AMETHYST = "minecraft:amethyst_block";
  const BUDDING = "minecraft:budding_amethyst";
  const LANTERN = "minecraft:sea_lantern";
  const FROGLIGHT = "minecraft:pearlescent_froglight";
  const GOLD = "minecraft:gold_block";
  const END_ROD = "minecraft:end_rod[facing=up]";
  const CLUSTER_UP = "minecraft:amethyst_cluster[facing=up]";
  const CLUSTER_N = "minecraft:amethyst_cluster[facing=north]";
  const CLUSTER_S = "minecraft:amethyst_cluster[facing=south]";
  const CLUSTER_E = "minecraft:amethyst_cluster[facing=east]";
  const CLUSTER_W = "minecraft:amethyst_cluster[facing=west]";

  function getStairs(baseStairs, facing, half = "bottom") {
    const base = baseStairs.split("[")[0];
    return `${base}[facing=${facing},half=${half}]`;
  }
  function getSlab(baseSlab, type = "bottom") {
    const base = baseSlab.split("[")[0];
    return `${base}[type=${type}]`;
  }

  // 3D Voxel Grid Buffer
  const grid = new Array(W * H * D).fill(null);
  const idx = (x, y, z) => x + y * W + z * W * H;

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[idx(x, y, z)] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[idx(x, y, z)];
    }
    return null;
  }

  // Distance to line segment with tapering radius
  function distConeSeg(px, py, pz, x1, y1, z1, r1, x2, y2, z2, r2) {
    const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
    const l2 = dx * dx + dy * dy + dz * dz;
    if (l2 === 0) {
      const ex = px - x1, ey = py - y1, ez = pz - z1;
      return Math.sqrt(ex * ex + ey * ey + ez * ez) - r1;
    }
    let t = ((px - x1) * dx + (py - y1) * dy + (pz - z1) * dz) / l2;
    t = Math.max(0, Math.min(1, t));
    const qx = x1 + t * dx, qy = y1 + t * dy, qz = z1 + t * dz;
    const ex = px - qx, ey = py - qy, ez = pz - qz;
    const r = r1 + t * (r2 - r1);
    return Math.sqrt(ex * ex + ey * ey + ez * ez) - r;
  }

  function ellipsoidVal(px, py, pz, cx, cy, cz, rx, ry, rz) {
    const dx = (px - cx) / rx;
    const dy = (py - cy) / ry;
    const dz = (pz - cz) / rz;
    return dx * dx + dy * dy + dz * dz;
  }

  // --- 1. FORTIFIED SANCTUARY BASTION (Base) ---
  function isBastionColumn(x, z) {
    const dx = Math.abs(x - 11);
    const dz = Math.abs(z - 13);
    // Central octagonal core
    if (dx <= 8 && dz <= 9 && (dx + dz) <= 13) return true;
    // 4 Corner Turrets
    if ((x - 5) ** 2 + (z - 6) ** 2 <= 10.5) return true;
    if ((x - 17) ** 2 + (z - 6) ** 2 <= 10.5) return true;
    if ((x - 5) ** 2 + (z - 20) ** 2 <= 10.5) return true;
    if ((x - 17) ** 2 + (z - 20) ** 2 <= 10.5) return true;
    // Grand North steps
    if (x >= 8 && x <= 14 && z >= 2 && z <= 5) return true;
    // Rear South buttress
    if (x >= 8 && x <= 14 && z >= 21 && z <= 24) return true;
    return false;
  }

  function isTurret(x, z) {
    return (
      (x - 5) ** 2 + (z - 6) ** 2 <= 10.5 ||
      (x - 17) ** 2 + (z - 6) ** 2 <= 10.5 ||
      (x - 5) ** 2 + (z - 20) ** 2 <= 10.5 ||
      (x - 17) ** 2 + (z - 20) ** 2 <= 10.5
    );
  }

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (!isBastionColumn(x, z)) continue;

      // Determine height of bastion terrace
      let topY = 14;
      if (isTurret(x, z)) {
        topY = 15;
      } else if (z <= 5 && x >= 8 && x <= 14) {
        // Stepped North entrance
        topY = Math.min(14, 8 + Math.floor((z - 2) * 1.6));
      } else if (z >= 21 && x >= 8 && x <= 14) {
        // Stepped South rear ramp
        topY = Math.min(14, 8 + Math.floor((24 - z) * 1.6));
      }

      // Conforming skirt to terrain height
      const localH = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(topY, seatY + localH));

      for (let y = groundY; y <= topY; y++) {
        let block = stonePrimary;
        const isEdge =
          !isBastionColumn(x + 1, z) ||
          !isBastionColumn(x - 1, z) ||
          !isBastionColumn(x, z + 1) ||
          !isBastionColumn(x, z - 1);

        if (y === groundY) {
          block = groundPlinth;
        } else if (y === topY) {
          if (z <= 5 && x >= 8 && x <= 14) {
            block = getStairs(stoneStairsRaw, "north");
          } else if (z >= 21 && x >= 8 && x <= 14) {
            block = getStairs(stoneStairsRaw, "south");
          } else if (isTurret(x, z)) {
            block = stoneAccent;
          } else {
            // Deck paving pattern
            const distCenter = Math.hypot(x - 11, z - 13);
            if (distCenter < 2.5) {
              block = FROGLIGHT;
            } else if (Math.abs(x - 11) === 3 || Math.abs(z - 13) === 3) {
              block = Q_BRICKS;
            } else {
              block = groundPave;
            }
          }
        } else {
          // Walls & pillars
          if (isEdge) {
            block = (y % 3 === 0) ? stoneAccent : stonePrimary;
          } else {
            block = stonePrimary;
          }
        }
        put(x, y, z, block);
      }
    }
  }

  // --- 2. HOLLOW INTERIOR SANCTUM VAULT (y = 9 to 13) ---
  for (let x = 8; x <= 14; x++) {
    for (let z = 9; z <= 17; z++) {
      put(x, 8, z, groundPave); // Solid floor
      for (let y = 9; y <= 13; y++) {
        put(x, y, z, null); // Furnishable empty space
      }
    }
  }

  // Open walk-in arched gateways connecting outdoors to vault
  for (let x = 10; x <= 12; x++) {
    for (let y = 9; y <= 12; y++) {
      for (let z = 4; z <= 8; z++) put(x, y, z, null); // North entry
      for (let z = 18; z <= 22; z++) put(x, y, z, null); // South entry
    }
  }

  // Vault ceiling arch ribs
  for (let x = 8; x <= 14; x++) {
    for (const z of [10, 13, 16]) {
      put(x, 13, z, stoneAccent);
    }
  }
  // Central crystalline shrine brazier in the vault
  put(11, 8, 13, GOLD);
  put(11, 9, 13, LANTERN);
  put(11, 10, 13, CLUSTER_UP);

  // --- 3. BASTION TURRETS & BATTLEMENTS ---
  const turrets = [
    [5, 6], [17, 6], [5, 20], [17, 20]
  ];
  for (const [tx, tz] of turrets) {
    // Turret beacon
    put(tx, 15, tz, LANTERN);
    put(tx, 16, tz, CLUSTER_UP);
    // Turret perimeter wall
    for (let ox = -2; ox <= 2; ox++) {
      for (let oz = -2; oz <= 2; oz++) {
        const d2 = ox * ox + oz * oz;
        if (d2 >= 4 && d2 <= 7) {
          put(tx + ox, 16, tz + oz, stoneWall);
        }
      }
    }
  }

  // Main deck battlements
  for (let x = 3; x <= 19; x++) {
    for (let z = 4; z <= 22; z++) {
      if (!isBastionColumn(x, z) || isTurret(x, z)) continue;
      if (get(x, 14, z) !== null && get(x, 15, z) === null) {
        const isBorder =
          !isBastionColumn(x + 1, z) ||
          !isBastionColumn(x - 1, z) ||
          !isBastionColumn(x, z + 1) ||
          !isBastionColumn(x, z - 1);
        // Leave open stair paths
        if (isBorder && !(x >= 9 && x <= 13 && (z <= 6 || z >= 20))) {
          if ((x + z) % 2 === 0) {
            put(x, 15, z, stoneWall);
          } else {
            put(x, 15, z, getSlab(stoneSlabRaw, "bottom"));
          }
        }
      }
    }
  }

  // --- 4. REARING CELESTIAL UNICORN COLOSSUS ---
  for (let x = 1; x < W - 1; x++) {
    for (let y = 14; y < H; y++) {
      for (let z = 0; z < D; z++) {

        // --- Anatomical SDF Distance Checks ---
        // Hind Left Leg (solidly anchored to deck at y=14)
        const dHindHoofL = distConeSeg(x, y, z, 8.0, 14.0, 16.5, 1.3, 8.0, 16.5, 16.5, 1.25);
        const dHindHockL = distConeSeg(x, y, z, 8.0, 16.5, 16.5, 1.25, 8.0, 19.5, 18.2, 1.4);
        const dHindThighL = distConeSeg(x, y, z, 8.0, 19.5, 18.2, 1.4, 8.5, 23.5, 16.2, 2.1);
        const dHindL = Math.min(dHindHoofL, dHindHockL, dHindThighL);

        // Hind Right Leg (solidly anchored to deck at y=14)
        const dHindHoofR = distConeSeg(x, y, z, 14.0, 14.0, 16.5, 1.3, 14.0, 16.5, 16.5, 1.25);
        const dHindHockR = distConeSeg(x, y, z, 14.0, 16.5, 16.5, 1.25, 14.0, 19.5, 18.2, 1.4);
        const dHindThighR = distConeSeg(x, y, z, 14.0, 19.5, 18.2, 1.4, 13.5, 23.5, 16.2, 2.1);
        const dHindR = Math.min(dHindHoofR, dHindHockR, dHindThighR);

        // Pelvis & Croup
        const dPelvis = ellipsoidVal(x, y, z, 11.0, 23.5, 16.0, 3.2, 2.5, 2.8) - 1.0;

        // Torso / Deep Barrel Chest (Rearing ~50 deg upward towards North)
        const dTorsoLow = distConeSeg(x, y, z, 11.0, 23.5, 16.0, 2.9, 11.0, 26.5, 13.0, 3.2);
        const dTorsoHigh = distConeSeg(x, y, z, 11.0, 26.5, 13.0, 3.2, 11.0, 29.0, 10.0, 3.4);
        const dChestProw = ellipsoidVal(x, y, z, 11.0, 27.5, 9.2, 2.5, 2.7, 2.2) - 1.0;
        const dBody = Math.min(dPelvis, dTorsoLow, dTorsoHigh, dChestProw);

        // Front Left Leg (Reared High in Battle Stance)
        const dForeShoulderL = distConeSeg(x, y, z, 8.0, 27.5, 10.5, 1.5, 7.2, 30.5, 8.0, 1.2);
        const dForeShinL = distConeSeg(x, y, z, 7.2, 30.5, 8.0, 1.2, 7.0, 28.0, 5.5, 1.0);
        const dForeHoofL = distConeSeg(x, y, z, 7.0, 28.0, 5.5, 1.0, 7.0, 26.5, 4.5, 0.9);
        const dForeL = Math.min(dForeShoulderL, dForeShinL, dForeHoofL);

        // Front Right Leg (Striking Higher forward toward the pirate fleet)
        const dForeShoulderR = distConeSeg(x, y, z, 14.0, 27.5, 10.5, 1.5, 14.5, 32.0, 7.5, 1.2);
        const dForeShinR = distConeSeg(x, y, z, 14.5, 32.0, 7.5, 1.2, 14.0, 30.0, 4.5, 1.0);
        const dForeHoofR = distConeSeg(x, y, z, 14.0, 30.0, 4.5, 1.0, 13.8, 28.5, 3.5, 0.9);
        const dForeR = Math.min(dForeShoulderR, dForeShinR, dForeHoofR);

        // Arched Equine Neck
        const dNeck1 = distConeSeg(x, y, z, 11.0, 29.0, 10.0, 2.5, 11.0, 32.2, 8.0, 2.0);
        const dNeck2 = distConeSeg(x, y, z, 11.0, 32.2, 8.0, 2.0, 11.0, 34.5, 6.2, 1.7);
        const dNeck = Math.min(dNeck1, dNeck2);

        // Head, Muzzle & Ears
        const dSkull = ellipsoidVal(x, y, z, 11.0, 34.5, 5.8, 1.6, 1.6, 1.9) - 1.0;
        const dMuzzle = distConeSeg(x, y, z, 11.0, 33.5, 5.2, 1.3, 11.0, 32.2, 3.5, 0.95);
        const dEarL = distConeSeg(x, y, z, 9.8, 35.5, 6.2, 0.7, 9.0, 37.5, 6.8, 0.25);
        const dEarR = distConeSeg(x, y, z, 12.2, 35.5, 6.2, 0.7, 13.0, 37.5, 6.8, 0.25);
        const dHead = Math.min(dSkull, dMuzzle, dEarL, dEarR);

        // Radiant Horn (Angles forward-up towards North: -Z)
        const dHorn = distConeSeg(x, y, z, 11.0, 35.2, 5.0, 0.85, 11.0, 40.5, 1.0, 0.35);

        // Cascading Crystal Tail (Sweeps down and anchors into bastion deck at y=14)
        const dTail1 = distConeSeg(x, y, z, 11.0, 23.5, 17.5, 1.4, 11.0, 19.5, 20.5, 1.6);
        const dTail2 = distConeSeg(x, y, z, 11.0, 19.5, 20.5, 1.6, 11.0, 15.5, 22.2, 1.8);
        const dTail3 = distConeSeg(x, y, z, 11.0, 15.5, 22.2, 1.8, 11.0, 14.0, 22.8, 2.1);
        const dTailFlankL = distConeSeg(x, y, z, 9.5, 17.0, 20.2, 0.9, 9.0, 14.0, 21.2, 1.1);
        const dTailFlankR = distConeSeg(x, y, z, 12.5, 17.0, 20.2, 0.9, 13.0, 14.0, 21.2, 1.1);
        const dTail = Math.min(dTail1, dTail2, dTail3, dTailFlankL, dTailFlankR);

        // Flowing Crystal Mane (Along dorsal crest of the neck)
        const dMane1 = distConeSeg(x, y, z, 11.0, 30.5, 10.8, 1.1, 11.0, 33.2, 9.0, 1.2);
        const dMane2 = distConeSeg(x, y, z, 11.0, 33.2, 9.0, 1.2, 11.0, 35.5, 7.5, 1.0);
        const dMane = Math.min(dMane1, dMane2);

        // Celestial Aegis Wings (Sweeping back from shoulders)
        // Left Wing
        const dWingStrutL = distConeSeg(x, y, z, 9.0, 28.5, 11.5, 1.1, 6.0, 30.5, 13.5, 0.95);
        const dWingTipL = distConeSeg(x, y, z, 6.0, 30.5, 13.5, 0.95, 3.5, 34.0, 16.2, 0.8);
        const dWingBlade1L = distConeSeg(x, y, z, 4.5, 31.5, 15.0, 0.7, 3.0, 26.5, 16.5, 0.65);
        const dWingBlade2L = distConeSeg(x, y, z, 6.0, 29.5, 13.5, 0.75, 5.0, 24.5, 15.0, 0.7);
        const dWingBlade3L = distConeSeg(x, y, z, 7.5, 28.0, 12.5, 0.8, 7.0, 23.5, 13.5, 0.75);
        const dWingL = Math.min(dWingStrutL, dWingTipL, dWingBlade1L, dWingBlade2L, dWingBlade3L);

        // Right Wing (Symmetrical)
        const dWingStrutR = distConeSeg(x, y, z, 13.0, 28.5, 11.5, 1.1, 16.0, 30.5, 13.5, 0.95);
        const dWingTipR = distConeSeg(x, y, z, 16.0, 30.5, 13.5, 0.95, 18.5, 34.0, 16.2, 0.8);
        const dWingBlade1R = distConeSeg(x, y, z, 17.5, 31.5, 15.0, 0.7, 19.0, 26.5, 16.5, 0.65);
        const dWingBlade2R = distConeSeg(x, y, z, 16.0, 29.5, 13.5, 0.75, 17.0, 24.5, 15.0, 0.7);
        const dWingBlade3R = distConeSeg(x, y, z, 14.5, 28.0, 12.5, 0.8, 15.0, 23.5, 13.5, 0.75);
        const dWingR = Math.min(dWingStrutR, dWingTipR, dWingBlade1R, dWingBlade2R, dWingBlade3R);
        const dWings = Math.min(dWingL, dWingR);

        // Combine all anatomical distance fields
        const minBodyDist = Math.min(dHindL, dHindR, dBody, dForeL, dForeR, dNeck, dHead);

        // --- Voxel Assignment ---
        if (dHorn <= 0) {
          if (y >= 39) {
            put(x, y, z, FROGLIGHT);
          } else if (y >= 37) {
            put(x, y, z, Q_PILLAR_Z);
          } else {
            put(x, y, z, AMETHYST);
          }
        } else if (dTail <= 0) {
          // Waterfall of crystal tail
          if ((x + y + z) % 3 === 0) {
            put(x, y, z, BUDDING);
          } else {
            put(x, y, z, AMETHYST);
          }
        } else if (dMane <= 0) {
          // Prismatic crystalline mane
          put(x, y, z, ((y + z) % 2 === 0) ? BUDDING : AMETHYST);
        } else if (dWings <= 0) {
          // Swept crystal wings
          if (y >= 32 || (x <= 4 || x >= 18)) {
            put(x, y, z, AMETHYST);
          } else {
            put(x, y, z, Q_SMOOTH);
          }
        } else if (minBodyDist <= 0) {
          // Hoof Tips
          if (
            (y <= 15 && (x === 8 || x === 14) && z === 16) ||
            (y === 26 && x === 7 && z === 4) ||
            (y === 28 && x === 14 && z === 3)
          ) {
            put(x, y, z, GOLD);
          }
          // Glowing Celestial Heart Core inside chest
          else if (x === 11 && y === 27 && z === 11) {
            put(x, y, z, FROGLIGHT);
          }
          // Glowing Eyes
          else if ((x === 9 || x === 13) && y === 34 && z === 5) {
            put(x, y, z, LANTERN);
          }
          // Equine Muscular Anatomy (Pristine Quartz & Marble)
          else {
            if ((x + y + z) % 5 === 0) {
              put(x, y, z, Q_BLOCK);
            } else {
              put(x, y, z, Q_SMOOTH);
            }
          }
        }
      }
    }
  }

  // --- 5. CRYSTALLINE DETAILS & HORN BEACON ---
  // Glowing horn tip reaching high toward the northern sky
  put(11, 41, 1, END_ROD);

  // Amethyst clusters along horn and mane
  put(11, 36, 4, CLUSTER_N);
  put(11, 38, 2, CLUSTER_N);
  put(10, 37, 3, CLUSTER_W);
  put(12, 37, 3, CLUSTER_E);

  // Mane clusters
  put(11, 36, 8, CLUSTER_UP);
  put(11, 34, 10, CLUSTER_UP);
  put(11, 31, 11, CLUSTER_UP);

  // Wing tip crystal clusters
  put(3, 35, 16, CLUSTER_UP);
  put(19, 35, 16, CLUSTER_UP);

  // Tail crystal clusters
  put(11, 20, 21, CLUSTER_UP);
  put(11, 16, 23, CLUSTER_UP);
  put(11, 14, 24, CLUSTER_S);

  // --- 6. EMIT TO WORLD ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[idx(x, y, z)];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "celestial_unicorn_colossus",
    seatY: 8,
    anchors: {
      front: [11, 8, 0],
      door: [11, 8, 2],
      horn_tip: [11, 41, 1],
      sanctuary_deck: [11, 14, 13]
    },
    interiors: [
      { min: [8, 9, 9], max: [14, 13, 17], kind: "vault" }
    ]
  };
}

