export const envelope = [9, 14, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 4;
  const cz = 4;
  const cy = 7; // Crystal focus center height

  // Resolve palette from theme with pristine arcane fallbacks
  const stonePrimary = api.theme.stone.primary || "minecraft:quartz_block";
  const stoneAccent = api.theme.stone.accent || "minecraft:smooth_quartz";
  const stoneStairs = api.theme.stone.stairs || "minecraft:quartz_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:quartz_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:diorite_wall";
  const groundPlinth = api.theme.ground.plinth || stonePrimary;
  const groundPavement = api.theme.ground.pavement || "minecraft:smooth_quartz";

  // Per-instance variance (6 distinct harmonic defense configurations)
  const inst = api.instance.index;
  const rng = () => api.random();

  const variant = inst % 3; // 0: Armillary Gyroscope, 1: Resonant Bastion Pylons, 2: Solar Corona Ward
  const copperAging = inst % 2 === 0 ? "minecraft:cut_copper" : "minecraft:waxed_copper_block";
  const copperStairs = inst % 2 === 0 ? "minecraft:cut_copper_stairs" : "minecraft:waxed_cut_copper_stairs";
  const copperSlab = inst % 2 === 0 ? "minecraft:cut_copper_slab" : "minecraft:waxed_cut_copper_slab";
  const goldBlock = "minecraft:gold_block";
  const amethystBlock = "minecraft:amethyst_block";
  const buddingAmethyst = "minecraft:budding_amethyst";
  const coreLight = variant === 0 ? "minecraft:beacon" : (variant === 1 ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");
  const glassAura = variant === 2 ? "minecraft:magenta_stained_glass" : "minecraft:purple_stained_glass";

  // Voxel storage to guarantee 6-connected integrity and clean placement
  const grid = new Map();
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set(`${x},${y},${z}`, { x, y, z, block });
    }
  }

  // Helper for cardinal stair direction
  function getStairFacing(dx, dz) {
    if (Math.abs(dz) >= Math.abs(dx)) {
      return dz < 0 ? "north" : "south";
    }
    return dx < 0 ? "west" : "east";
  }

  // -------------------------------------------------------------------------
  // 1. FOUNDATION & PLINTH DAIS (y = 0 to 2) with TERRAIN CONFORMANCE (Rule 6)
  // -------------------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const d2 = dx * dx + dz * dz;

      // Base footprint: octagonal/rounded dais (radius ~ 4.1)
      if (d2 <= 17.5) {
        const groundH = Math.floor(api.heightAt(x, z));
        const startY = Math.min(0, groundH);

        // Sub-seat foundation skirt down to uneven terrain
        for (let y = startY; y < 0; y++) {
          setBlock(x, y, z, groundPlinth);
        }

        // Tier 0 (y = 0): Solid ground plinth
        setBlock(x, 0, z, d2 <= 9 ? stoneAccent : groundPlinth);

        // Tier 1 (y = 1): Stepped terrace & runic perimeter
        if (d2 <= 11.0) {
          if (d2 <= 4.5) {
            setBlock(x, 1, z, (dx === 0 || dz === 0) ? copperAging : groundPavement);
          } else {
            setBlock(x, 1, z, stonePrimary);
          }
        } else if (d2 <= 17.0) {
          // Perimeter coping stairs facing outward
          const facing = getStairFacing(dx, dz);
          setBlock(x, 1, z, `${stoneStairs}[facing=${facing},half=bottom,shape=straight]`);
        }

        // Tier 2 (y = 2): Central altar pedestal
        if (d2 <= 5.0) {
          if (d2 <= 1.5) {
            setBlock(x, 2, z, goldBlock);
          } else {
            setBlock(x, 2, z, stoneAccent);
          }
        } else if (d2 <= 8.5) {
          const facing = getStairFacing(dx, dz);
          setBlock(x, 2, z, `${copperStairs}[facing=${facing},half=bottom,shape=straight]`);
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. CENTRAL FOCUS CONDUIT & ALTAR CORE (y = 3 to 4)
  // -------------------------------------------------------------------------
  // Pedestal hub channeling earth power up into the floating crystal
  for (let x = cx - 1; x <= cx + 1; x++) {
    for (let z = cz - 1; z <= cz + 1; z++) {
      setBlock(x, 3, z, stonePrimary);
    }
  }
  setBlock(cx, 3, cz, coreLight);
  setBlock(cx + 1, 3, cz, stoneWall);
  setBlock(cx - 1, 3, cz, stoneWall);
  setBlock(cx, 3, cz + 1, stoneWall);
  setBlock(cx, 3, cz - 1, stoneWall);

  // Focus emitter chalice (y = 4)
  setBlock(cx, 4, cz, goldBlock);
  setBlock(cx + 1, 4, cz, copperAging);
  setBlock(cx - 1, 4, cz, copperAging);
  setBlock(cx, 4, cz + 1, copperAging);
  setBlock(cx, 4, cz - 1, copperAging);

  // -------------------------------------------------------------------------
  // 3. ARCHING BRASS CRADLE ARMS (y = 2 to 12)
  // -------------------------------------------------------------------------
  // 4 Sweeping armature pylons at cardinal/diagonal anchors that curve up,
  // cage around the warding rings, and meet at the apex crown.
  const armOffsets = [
    { dx: -2, dz: -2 },
    { dx: 2, dz: -2 },
    { dx: -2, dz: 2 },
    { dx: 2, dz: 2 }
  ];

  for (const arm of armOffsets) {
    const ax = cx + arm.dx;
    const az = cz + arm.dz;

    // Plinth footing
    setBlock(ax, 2, az, copperAging);
    setBlock(ax, 3, az, stoneWall);
    setBlock(ax, 4, az, copperAging);

    // Mid-ribs sweeping outward to enclose the crystal
    const outwardX = cx + Math.round(arm.dx * 1.5);
    const outwardZ = cz + Math.round(arm.dz * 1.5);
    setBlock(outwardX, 5, outwardZ, goldBlock);
    setBlock(outwardX, 6, outwardZ, copperAging);
    setBlock(outwardX, 7, outwardZ, copperAging);
    setBlock(outwardX, 8, outwardZ, goldBlock);

    // Direct solid 6-connections between pylon nodes
    setBlock(ax, 5, az, copperAging);
    setBlock(outwardX, 5, az, copperAging);
    setBlock(ax, 5, outwardZ, copperAging);

    // Upper arches curving back inward
    setBlock(ax, 9, az, copperAging);
    setBlock(outwardX, 9, outwardZ, copperAging);
    setBlock(ax, 10, az, stoneWall);
    setBlock(cx + Math.sign(arm.dx), 11, cz + Math.sign(arm.dz), copperAging);
  }

  // Apex Crown at y = 12..13 (uniting all 4 arches)
  setBlock(cx, 12, cz, goldBlock);
  setBlock(cx + 1, 12, cz, copperAging);
  setBlock(cx - 1, 12, cz, copperAging);
  setBlock(cx, 12, cz + 1, copperAging);
  setBlock(cx, 12, cz - 1, copperAging);
  setBlock(cx, 13, cz, "minecraft:lightning_rod[facing=up]");

  // -------------------------------------------------------------------------
  // 4. ROTATING BRASS WARDING RINGS (y = 5 to 9)
  // -------------------------------------------------------------------------
  // Ring 1: Equatorial Brass Warding Ring (y = 7, radius ~ 3.2)
  for (let angleDeg = 0; angleDeg < 360; angleDeg += 15) {
    const rad = (angleDeg * Math.PI) / 180;
    const rx = Math.round(cx + 3.2 * Math.cos(rad));
    const rz = Math.round(cz + 3.2 * Math.sin(rad));
    setBlock(rx, cy, rz, (angleDeg % 45 === 0) ? goldBlock : copperAging);
  }

  // Ring 2: Inclined Resonant Gyroscope Ring (tilted 45 degrees)
  const tiltAxis = (variant === 0) ? 0.785 : (variant === 1 ? -0.785 : 0.0);
  for (let angleDeg = 0; angleDeg < 360; angleDeg += 12) {
    const rad = (angleDeg * Math.PI) / 180;
    const u = 2.8 * Math.cos(rad);
    const v = 2.8 * Math.sin(rad);

    const rx = Math.round(cx + u * Math.cos(tiltAxis));
    const rz = Math.round(cz + u * Math.sin(tiltAxis));
    const ry = Math.round(cy + v * 0.85);

    if (ry >= 4 && ry <= 10) {
      setBlock(rx, ry, rz, (Math.abs(v) > 2.0) ? goldBlock : copperAging);
    }
  }

  // -------------------------------------------------------------------------
  // 5. LEVITATING AMETHYST FOCUS CRYSTAL (y = 5 to 10)
  // -------------------------------------------------------------------------
  // Faceted bipyramidal gem centered at (cx, cy, cz)
  // Base point (y = 5)
  setBlock(cx, 5, cz, amethystBlock);

  // Lower diamond tier (y = 6)
  setBlock(cx, 6, cz, buddingAmethyst);
  setBlock(cx + 1, 6, cz, amethystBlock);
  setBlock(cx - 1, 6, cz, amethystBlock);
  setBlock(cx, 6, cz + 1, amethystBlock);
  setBlock(cx, 6, cz - 1, amethystBlock);
  setBlock(cx + 1, 6, cz + 1, glassAura);
  setBlock(cx - 1, 6, cz + 1, glassAura);
  setBlock(cx + 1, 6, cz - 1, glassAura);
  setBlock(cx - 1, 6, cz - 1, glassAura);

  // Central Crystal Core Equator (y = 7)
  setBlock(cx, 7, cz, coreLight); // Glowing heart of the crystal
  setBlock(cx + 1, 7, cz, amethystBlock);
  setBlock(cx - 1, 7, cz, amethystBlock);
  setBlock(cx, 7, cz + 1, amethystBlock);
  setBlock(cx, 7, cz - 1, amethystBlock);
  setBlock(cx + 1, 7, cz + 1, glassAura);
  setBlock(cx - 1, 7, cz + 1, glassAura);
  setBlock(cx + 1, 7, cz - 1, glassAura);
  setBlock(cx - 1, 7, cz - 1, glassAura);

  // 6-Connected Energy Resonance Spines locking crystal to warding ring
  setBlock(cx + 2, 7, cz, copperAging);
  setBlock(cx - 2, 7, cz, copperAging);
  setBlock(cx, 7, cz + 2, copperAging);
  setBlock(cx, 7, cz - 2, copperAging);

  // Upper diamond tier (y = 8)
  setBlock(cx, 8, cz, buddingAmethyst);
  setBlock(cx + 1, 8, cz, amethystBlock);
  setBlock(cx - 1, 8, cz, amethystBlock);
  setBlock(cx, 8, cz + 1, amethystBlock);
  setBlock(cx, 8, cz - 1, amethystBlock);
  setBlock(cx + 1, 8, cz + 1, glassAura);
  setBlock(cx - 1, 8, cz + 1, glassAura);
  setBlock(cx + 1, 8, cz - 1, glassAura);
  setBlock(cx - 1, 8, cz - 1, glassAura);

  // Crystal apex tip (y = 9 to 10)
  setBlock(cx, 9, cz, amethystBlock);
  setBlock(cx, 10, cz, "minecraft:large_amethyst_bud[facing=up]");

  // -------------------------------------------------------------------------
  // 6. DEFENSIVE WARD RADIATORS & NORTH-FACING CANNON SHIELD (Rule 12)
  // -------------------------------------------------------------------------
  // North-facing cannon projectile deflectors (-Z direction towards pirate strait)
  setBlock(cx, 7, 0, "minecraft:lightning_rod[facing=north]");
  setBlock(cx, 7, 1, copperAging);
  setBlock(cx, 8, 1, "minecraft:end_rod[facing=up]");

  // Secondary resonance emitters
  setBlock(cx, 7, D - 1, "minecraft:lightning_rod[facing=south]");
  setBlock(0, 7, cz, "minecraft:lightning_rod[facing=west]");
  setBlock(W - 1, 7, cz, "minecraft:lightning_rod[facing=east]");

  // Amethyst resonance clusters blooming on crystal facets
  setBlock(cx + 1, 9, cz, "minecraft:amethyst_cluster[facing=east]");
  setBlock(cx - 1, 9, cz, "minecraft:amethyst_cluster[facing=west]");
  setBlock(cx, 9, cz + 1, "minecraft:amethyst_cluster[facing=south]");
  setBlock(cx, 9, cz - 1, "minecraft:amethyst_cluster[facing=north]");

  // Ground ward channeling stones around dais
  setBlock(cx + 3, 1, cz + 3, "minecraft:end_rod[facing=up]");
  setBlock(cx - 3, 1, cz + 3, "minecraft:end_rod[facing=up]");
  setBlock(cx + 3, 1, cz - 3, "minecraft:end_rod[facing=up]");
  setBlock(cx - 3, 1, cz - 3, "minecraft:end_rod[facing=up]");

  // -------------------------------------------------------------------------
  // 7. EMIT TO WORLD
  // -------------------------------------------------------------------------
  for (const { x, y, z, block } of grid.values()) {
    api.set(x, y, z, block);
  }

  return {
    name: "arcane_defense_crystal",
    seatY: 0,
    anchors: {
      front: [cx, 0, 0],       // Facing local North towards enemy bombardments
      focus: [cx, cy, cz],     // Arcane crystal core point
      apex: [cx, 13, cz]       // Lightning deflector tip
    }
  };
}
